    int k = l;
    if (l > nb) {
        k = 2 * nb - l;
    }
    String texte = "";
    for (int j = 0; j < nb - k; j++) {
        texte = texte + ".";
    }
    for (int j = 0; j < 2 * k - 1; j++) {
        texte = texte + "*";
    }
    for (int j = 0; j < nb - k; j++) {
        texte = texte + ".";
    }
    affiche(texte);
}

